CREATE TABLE copilot_configs(id TEXT PRIMARY KEY, manifest TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evaluation_runs(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), created_by TEXT NOT NULL REFERENCES users(id), config_id TEXT NOT NULL REFERENCES copilot_configs(id), dataset_version TEXT NOT NULL, dataset_sha256 TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN('no_rag','docs_rag','tools_rag')), started_at TEXT NOT NULL, finished_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('passed','failed')), report TEXT NOT NULL);
CREATE INDEX evaluation_runs_plant ON evaluation_runs(plant_id,finished_at);
CREATE TABLE evaluation_reviews(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES evaluation_runs(id), reviewer_id TEXT NOT NULL REFERENCES users(id), qualification TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN('accepted','rejected')), notes TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE copilot_releases(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), run_id TEXT NOT NULL REFERENCES evaluation_runs(id), baseline_id TEXT REFERENCES evaluation_runs(id), actor_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN('accepted','blocked')), reasons TEXT NOT NULL, created_at TEXT NOT NULL);
